const res = $input.first().json;
let content = res.choices && res.choices[0] && res.choices[0].message ? res.choices[0].message.content : (res.message ? res.message.content : '{}');
let data;
try { data = JSON.parse(content); }
catch (e) { const m = String(content).match(/\{[\s\S]*\}/); data = m ? JSON.parse(m[0]) : { error: 'parse_failed', raw: content }; }
['net','gst','total'].forEach(k => { if (typeof data[k] === 'string') data[k] = parseFloat(String(data[k]).replace(/[^0-9.\-]/g,'')) || 0; });
if (data.total == null && (data.net != null || data.gst != null)) data.total = (data.net || 0) + (data.gst || 0);
data.currency = data.currency || 'SGD';
return [{ json: data }];
